'use client';

import { motion } from 'framer-motion';
import Image from 'next/image';

const fadeTransition = { duration: 0.55, ease: [0.22, 1, 0.36, 1] as const };

const softwareLogos = [
  { name: 'Blender', src: 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTnJWv8OMc3xyH7Omf0GWQ2twaIKx_ft05uXQ&s' },
  { name: 'AutoCAD', src: 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcS12RJuHpi5fQAlJG2Ca0a_Q2EMyDhOUikLXQ&s' },
  { name: 'Premiere Pro', src: 'data:image/png;base64,' },
  { name: 'Photoshop', src: 'data:image/jpeg;base64,' },
  { name: 'After Effects', src: 'data:image/jpeg;base64, ' },
  { name: 'Maya', src: 'data:image/jpeg;base64,' },
  { name: 'Unity', src: 'data:image/png;base64,' },
  { name: 'VsCode', src: 'data:image/png;base64,' },
  { name: 'Unreal Engine', src: 'data:image/png;base64,' },
  { name: 'Figma', src: 'data:image/png;base64,' },
  { name: 'oracle virtualbox', src: 'data:image/png;base64,' },
  { name: 'DaVinci Resolve', src: 'data:image/jpeg;base64,' },
  ];

  export const folderLogos = [
  { name: 'Whatsapp', src: 'data:image/jpeg;base64,' },
  { name: 'Gmail', src: 'data:image/png;base64,' },
  { name: 'File Explorer', src: 'data:image/jpeg;base64,' },
  { name: 'Telegram', src: 'data:image/jpeg;base64,' },
  { name: 'Trash', src: 'data:image/jpeg;base64,' },
  { name: 'Spotify', src: 'data:image/png;base64,' },
 
  ];

export const platformLogos = [
  { name: 'Windows', src: 'data:image/png;base64,' },
  { name: 'macOS', src: 'data:image/png;base64,' },
  { name: 'Linux', src: 'data:image/png;base64,' },
];

export function SoftwareLogos({ className = '', showLabels = false }: { className?: string; showLabels?: boolean }) {
  return (
    <div className={`flex flex-wrap items-center gap-4 ${className}`}>
      {softwareLogos.map((software, i) => (
        <motion.div
          key={software.name}
          initial={{ opacity: 0, scale: 0.9 }}
          whileInView={{ opacity: 1, scale: 1 }}
          viewport={{ once: true }}
          transition={{ ...fadeTransition, delay: i * 0.05 }}
          className="group relative"
        >
          {/* Parent div defines the final shape */}
          <div className="relative w-12 h-12 rounded-xl bg-white/5 border border-white/10 flex items-center justify-center overflow-hidden transition-all duration-300 group-hover:border-white/20 group-hover:bg-white/10">
            <Image
              src={software.src}
              alt={software.name}
              /* Use fill to cover the entire div area */
              fill
              className="object-cover transition-transform duration-300 group-hover:scale-110"
              unoptimized
            />
          </div>
          {showLabels && (
            <span className="text-xs text-neutral-400 font-medium ml-2">{software.name}</span>
          )}
          <div className="absolute -bottom-8 left-1/2 -translate-x-1/2 px-2 py-1 bg-black/80 text-white text-[10px] font-medium rounded opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap pointer-events-none">
            {software.name}
          </div>
        </motion.div>
      ))}
    </div>
  );
}

export function PlatformLogos({ className = '' }: { className?: string }) {
  return (
    <div className={`flex items-center gap-6 ${className}`}>
      {platformLogos.map((platform, i) => (
        <motion.div
          key={platform.name}
          initial={{ opacity: 0, y: 8 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ ...fadeTransition, delay: i * 0.1 }}
          className="relative group"
        >
          <div className="flex items-center gap-2">
            {/* Parent div handles the rounded-lg shape */}
            <div className="relative w-10 h-10 rounded-lg bg-white/5 border border-white/10 overflow-hidden">
              <Image
                src={platform.src}
                alt={platform.name}
                fill
                className="object-cover"
                unoptimized
              />
            </div>
            <span className="text-sm font-medium text-neutral-300">{platform.name}</span>
          </div>
          <div className="absolute -bottom-8 left-1/2 -translate-x-1/2 px-2 py-1 bg-black/80 text-white text-[10px] font-medium rounded opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap pointer-events-none">
            {platform.name}
          </div>
        </motion.div>
      ))}
    </div>
  );
}

export function SoftwareLogosWithHover({ className = '' }: { className?: string }) {
  return <SoftwareLogos className={className} showLabels={false} />;
}

export function SoftwareLogosMarquee({ className = '' }: { className?: string }) {
  const itemWidth = 48 + 24;
  
  const marqueeItems = [
    { type: 'folder', apps: ['Whatsapp', 'Telegram', 'Trash'] },
    { type: 'folder', apps: ['File Explorer', 'Spotify', 'Gmail'] },
    ...softwareLogos,
  ];
  
  const duplicatedItems = [...marqueeItems, ...marqueeItems, ...marqueeItems];
  const totalWidth = marqueeItems.length * itemWidth;
  
  const FolderIcon = ({ apps, hoverContent }: { apps: string[]; hoverContent?: boolean }) => (
    <div className="relative w-12 h-12 rounded-xl bg-gradient-to-br from-[#3a3a3c] to-[#1c1c1e] border border-white/20 shadow-xl overflow-hidden group">
      <div className="absolute inset-0.5 bg-gradient-to-br from-[#2c2c2e] to-[#1c1c1e] rounded-lg">
        <div className="absolute inset-0 flex flex-col items-center justify-center gap-0.5 p-0.5">
          <div className="flex gap-0.5">
            {apps.slice(0, 2).map((app) => {
              const appData = folderLogos.find(f => f.name.toLowerCase() === app.toLowerCase());
              return appData ? (
                <div key={app} className="relative w-4 h-4 rounded-sm overflow-hidden border border-white/20">
                  <Image src={appData.src} alt={app} fill className="object-cover" unoptimized />
                </div>
              ) : null;
            })}
          </div>
          {apps[2] && (
            <div className="flex gap-0.5">
              {(() => {
                const appData = folderLogos.find(f => f.name.toLowerCase() === apps[2].toLowerCase());
                return appData ? (
                  <div className="relative w-4 h-4 rounded-sm overflow-hidden border border-white/20">
                    <Image src={appData.src} alt={apps[2]} fill className="object-cover" unoptimized />
                  </div>
                ) : null;
              })()}
            </div>
          )}
        </div>
      </div>
      {hoverContent && (
        <div className="absolute inset-0 bg-black/60 backdrop-blur-md rounded-xl opacity-0 group-hover:opacity-100 transition-opacity duration-300 flex items-center justify-center p-2">
          <div className="grid grid-cols-3 gap-1">
            {apps.map((app) => {
              const appData = folderLogos.find(f => f.name.toLowerCase() === app.toLowerCase());
              return appData ? (
                <div key={app} className="relative w-6 h-6 rounded-md overflow-hidden border border-white/30 shadow-sm">
                  <Image src={appData.src} alt={app} fill className="object-cover" unoptimized />
                </div>
              ) : null;
            })}
          </div>
        </div>
      )}
    </div>
  );
  
  return (
    <div className={`relative overflow-hidden w-full ${className}`}>
      <div className="absolute left-0 top-0 bottom-0 w-20 bg-gradient-to-r from-[#050505] to-transparent z-10 pointer-events-none" />
      <div className="absolute right-0 top-0 bottom-0 w-20 bg-gradient-to-l from-[#050505] to-transparent z-10 pointer-events-none" />
      
      <motion.div
        className="flex items-center gap-6 w-max"
        animate={{ x: [0, -totalWidth] }}
        transition={{
          duration: 30,
          repeat: Infinity,
          ease: 'linear',
        }}
        style={{
          width: 'max-content',
        }}
      >
        {duplicatedItems.map((item: any, i: number) => (
          <div
            key={item.type === 'folder' ? `folder-${item.apps.join('-')}-${i}` : `${item.name}-${i}`}
            className="relative flex-shrink-0"
          >
            {item.type === 'folder' ? (
              <FolderIcon apps={item.apps} hoverContent={true} />
            ) : (
              <div className="relative w-12 h-12 rounded-xl bg-white/5 border border-white/10 flex items-center justify-center overflow-hidden transition-all duration-300 hover:border-white/20 hover:bg-white/10">
                <Image
                  src={item.src}
                  alt={item.name}
                  fill
                  className="object-cover transition-transform duration-300 hover:scale-110"
                  unoptimized
                />
              </div>
            )}
          </div>
        ))}
      </motion.div>
    </div>
  );
}
